def copy_material_to_materials(apps, schema_editor):
    Component = apps.get_model('materials', 'Component')
    for component in Component.objects.all():
        if component.material:
            component.materials.add(component.material)

def reverse_copy_material_to_materials(apps, schema_editor):
    Component = apps.get_model('materials', 'Component')
    for component in Component.objects.all():
        # Taking the first material if any, as we can't perfectly reverse M2M to FK if >1
        first_material = component.materials.first()
        if first_material:
            component.material = first_material
            component.save()


